const D = { energy:.5, scale:1, hue:150, curtains:.7, pines:.6, stars:.7, snow:.5, moon:.4, x:.5, y:.5, speed:1, density:.5, style:'green', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const hor=H*(0.62+(P.y-0.5)*0.3);

let skyT=[240,70,10], skyB=[230,50,20], auroraHs=[140,170,110], snowc=[210,10,86], pinec=[210,30,10];
if(sty==='purple'){ skyT=[260,70,10]; skyB=[250,55,22]; auroraHs=[280,320,200]; snowc=[260,12,84]; pinec=[260,35,9]; }
else if(sty==='red'){ skyT=[250,60,10]; skyB=[280,50,20]; auroraHs=[350,20,320]; snowc=[250,10,82]; pinec=[250,30,9]; }
else if(sty==='arctic'){ skyT=[210,75,12]; skyB=[195,55,28]; auroraHs=[180,150,200]; snowc=[195,12,90]; pinec=[200,35,10]; }
else if(sty==='twilight'){ skyT=[255,55,14]; skyB=[20,55,40]; auroraHs=[140,180,300]; snowc=[30,15,86]; pinec=[250,30,10]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }

// sky
let g=dc.createLinearGradient(0,0,0,hor); g.addColorStop(0,Cc(skyT,100).toString()); g.addColorStop(1,Cc(skyB,100).toString()); dc.fillStyle=g; noStroke(); rect(0,0,W,hor+1);
// stars
if(P.stars>0.05){ for(let i=0;i<P.stars*160;i++){ const x=fr(i)*W,y=fr(i+50)*hor*0.85; const tw=0.4+0.6*Math.sin(t*(1+fr(i)*2)+fr(i)*7); fill(Cc([210,8,100],25+tw*55)); circle(x,y,0.6+fr(i+3)*1.3);} }
// moon
if(P.moon>0.05){ const mr=P.moon*34+12,mx=W*0.78,my=hor*0.35; dc.save(); dc.shadowBlur=28; dc.shadowColor=Cc([210,12,98],60).toString(); fill(Cc([210,12,98],100)); circle(mx,my,mr*2); dc.restore(); fill(Cc(skyT,55)); circle(mx+mr*0.4,my-mr*0.3,mr*1.4); }
// AURORA curtains — flowing bands, incommensurate waves (large-area motion)
if(P.curtains>0.05){ dc.save(); blendMode(SCREEN);
  const nc=Math.floor(3+P.curtains*4);
  for(let b=0;b<nc;b++){ const hue=auroraHs[b%auroraHs.length]; const baseY=hor*(0.2+b*0.13);
    for(let layer=0;layer<4;layer++){ noFill(); stroke(color(hue,70,85, (8+P.curtains*10)*P.alpha/100)); strokeWeight(14-layer*3);
      beginShape();
      for(let x=-20;x<=W+20;x+=W/40){ const w1=Math.sin(x*0.004+t*(0.3+en*0.3)*P.speed + b*2)*40; const w2=Math.sin(x*0.011+t*0.5+b)*20; const drop=layer*14 + (Math.sin(x*0.006+t*0.4+b)*0.5+0.5)*70*P.curtains; vertex(x, baseY+w1+w2+drop); }
      endShape(); }
    // vertical ray shimmer
    for(let r=0;r<Math.floor(W/60);r++){ const rx=r*60+ (t*8)%60; const rh=(0.4+fr(r+b)*0.6)*hor*0.5*P.curtains; stroke(color(hue,60,90, 4*P.alpha/100)); strokeWeight(3); line(rx, baseY, rx, baseY+rh); }
  }
  dc.restore(); blendMode(BLEND);
}
// ground snow
let g2=dc.createLinearGradient(0,hor,0,H); g2.addColorStop(0,Cc([snowc[0],snowc[1],snowc[2]],100).toString()); g2.addColorStop(1,Cc([snowc[0],snowc[1]+6,snowc[2]-24],100).toString()); dc.fillStyle=g2; rect(0,hor,W,H-hor+1);
// aurora reflection on snow
if(P.curtains>0.05){ dc.save(); blendMode(SCREEN); fill(color(auroraHs[0],50,80, 8*P.curtains*P.alpha/100)); rect(0,hor,W,H*0.25); dc.restore(); blendMode(BLEND); }
// snow sparkle
if(P.snow>0.05){ noStroke(); for(let i=0;i<P.snow*60;i++){ const x=fr(i+8)*W,y=hor+fr(i+3)*(H-hor); const tw=Math.sin(t*3+i*7); if(tw>0.7){ fill(Cc([210,5,100],tw*60)); circle(x,y,1.4);} } }
// pines silhouette
if(P.pines>0.05){ noStroke(); fill(Cc(pinec,100)); const np=Math.floor(4+P.pines*12); for(let i=0;i<np;i++){ const x=fr(i*3)*W; const ph=(0.08+fr(i)*0.16)*H*P.pines; const pw=ph*0.32; for(let s=0;s<3;s++){ const yy=hor-s*ph*0.28; triangle(x-pw*(1-s*0.25),yy, x+pw*(1-s*0.25),yy, x,yy-ph*0.55);} rect(x-3,hor-6,6,10); } }
blendMode(BLEND); dc.shadowBlur=0;
